const item = $input.first();
const body = item.json.body || {};
const binary = item.binary || {};

const errors = [];

const binaryKey = Object.keys(binary)[0];
if (!binaryKey) {
  errors.push('Nenhum arquivo PDF enviado (campo curriculum)');
} else {
  const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  if (!pdfBuffer || pdfBuffer.length < 100) {
    errors.push('Arquivo PDF vazio ou corrompido');
  } else {
    const header = pdfBuffer.slice(0, 5).toString('ascii');
    if (header !== '%PDF-') {
      errors.push('Arquivo nao e um PDF valido (magic bytes invalidos)');
    }
    if (pdfBuffer.length > 10 * 1024 * 1024) {
      errors.push('PDF excede tamanho maximo de 10MB');
    }
  }
}

const jobTitle = body.job_title || '';
if (!jobTitle || jobTitle.trim().length === 0) {
  errors.push('Campo job_title e obrigatorio');
} else if (jobTitle.length > 200) {
  errors.push('job_title excede 200 caracteres');
}

const jobDesc = body.job_description || '';
if (!jobDesc || jobDesc.trim().length === 0) {
  errors.push('Campo job_description e obrigatorio');
} else if (jobDesc.trim().length < 10) {
  errors.push('job_description muito curta (minimo 10 caracteres)');
} else if (jobDesc.length > 50000) {
  errors.push('job_description excede 50000 caracteres');
}

if (errors.length > 0) {
  return [{ json: { _security_failed: true, _stage: 'validacao', error: 'Dados de entrada invalidos', details: errors.map(e => `Campo invalido: ${e}`) } }];
}

return [{ json: { ...body, _binary_key: binaryKey, _security_failed: false }, binary: $input.first().binary }];

const item = $input.first();
const data = item.json;

if (data._security_failed) {
  return [{ json: data }];
}

const output = data.output || '';

try {
  // remove qualquer bloco de raciocinio (modelos "reasoning" tipo <think>...</think>)
  let cleaned = output.replace(/<think>[\s\S]*?<\/think>/gi, '');
  // remove cercas de markdown
  cleaned = cleaned.replace(/```json|```/g, '').trim();

  // procura todos os objetos JSON no texto restante e usa o ULTIMO valido
  // (evita pegar sobras de raciocinio que nao foram fechadas por </think>)
  const candidates = cleaned.match(/\{[^{}]*"safe"[^{}]*\}/g);

  if (!candidates || candidates.length === 0) {
    throw new Error('Resposta da IA nao contem JSON com campo "safe"');
  }

  const lastCandidate = candidates[candidates.length - 1];
  const result = JSON.parse(lastCandidate);

  if (typeof result.safe !== 'boolean') {
    throw new Error('Campo "safe" ausente ou invalido na resposta da IA');
  }

  if (result.safe === false) {
    return [{
      json: {
        _security_failed: true,
        _stage: 'ia_security',
        error: 'Conteudo bloqueado por analise de IA',
        details: [result.reason || 'Motivo nao especificado pela IA']
      }
    }];
  }

  return [{ json: { ...data, _security_failed: false }, binary: $('Validacao de Dados').first().binary }];

} catch (e) {
  return [{
    json: {
      _security_failed: true,
      _stage: 'ia_security',
      error: 'Nao foi possivel validar a seguranca do conteudo',
      details: [`Erro ao interpretar resposta da IA: ${e.message}`]
    }
  }];
}

const data = $('Validacao de Dados').first().json;
const binaryKey = data._binary_key;

const jobTitle = data.job_title || '';
const jobDescription = data.job_description || '';

const bin = $('Validacao de Dados').first().binary;
const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);

// sanitiza o filename: remove CRLF e aspas para nao quebrar o header Content-Disposition
let pdfName = (bin && bin[binaryKey]) ? bin[binaryKey].fileName : 'curriculo.pdf';
pdfName = String(pdfName).replace(/[\r\n"]/g, '').slice(0, 255);

// gera boundary aleatorio sem depender de require('crypto'),
// que e bloqueado pelo sandbox do node Code do n8n
function randomHex(bytes) {
  let hex = '';
  for (let i = 0; i < bytes; i++) {
    hex += Math.floor(Math.random() * 256).toString(16).padStart(2, '0');
  }
  return hex;
}
const boundary = '----FormBoundary' + randomHex(16) + Date.now().toString(16);

// se por algum motivo o texto do usuario contiver a string do boundary
// (praticamente impossivel dado que e aleatorio), rejeita em vez de seguir
if (jobTitle.includes(boundary) || jobDescription.includes(boundary)) {
  return [{ json: { _security_failed: true, _stage: 'multipart', error: 'Conteudo invalido', details: ['Colisao de boundary detectada'] } }];
}

const parts = [];
parts.push(`--${boundary}\r\nContent-Disposition: form-data; name="curriculum"; filename="${pdfName}"\r\nContent-Type: application/pdf\r\n\r\n`);
parts.push(pdfBuffer);
parts.push(`\r\n--${boundary}\r\nContent-Disposition: form-data; name="job_title"\r\n\r\n${jobTitle}`);
parts.push(`\r\n--${boundary}\r\nContent-Disposition: form-data; name="job_description"\r\n\r\n${jobDescription}`);
parts.push(`\r\n--${boundary}--\r\n`);

const bodyParts = parts.map(p => typeof p === 'string' ? Buffer.from(p, 'utf-8') : p);
const body = Buffer.concat(bodyParts);

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8001/analyze',
    headers: {
      'Content-Type': `multipart/form-data; boundary=${boundary}`,
    },
    body: body,
    json: false,
    returnFullResponse: false,
    timeout: 120000,
  });

  const parsed = typeof response === 'string' ? JSON.parse(response) : response;
  return [{ json: parsed }];

} catch (e) {
  return [{
    json: {
      _api_error: true,
      error: 'Falha ao processar o curriculo',
      details: [e.message || 'Erro desconhecido ao chamar a API de analise']
    }
  }];
}
